<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}">
<title>CareRoute · Emergency Bed Management</title>
<link rel="icon" href="{{ asset(config('branding.logo')) }}" type="image/svg+xml">
<style>
:root{--navy:#102e49;--teal:#087f78;--muted:#63758a;--line:#dce5eb;--bg:#f3f6f9}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--navy);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:0;border-radius:9px;padding:10px 15px;background:var(--teal);color:white;font-weight:650}button:hover{filter:brightness(.94)}button:disabled{opacity:.5;cursor:wait}.secondary{background:#e7eff4;color:var(--navy)}.danger{background:#fff0ee;color:#b3312c}header{background:white;border-bottom:1px solid var(--line);padding:18px 4%;display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{display:flex;align-items:center;gap:12px}.brand img{width:43px;height:43px}.brand strong{font-size:22px;letter-spacing:-.8px}.brand small{display:block;color:var(--muted);font-size:11px;letter-spacing:1px}.header-right{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.demo{font-size:11px;font-weight:700;padding:6px 10px;border-radius:20px;background:#fff5d9;color:#836016}main{max-width:1450px;margin:auto;padding:28px 4%}.hero{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:22px}h1{font-size:30px;letter-spacing:-1px;margin:0 0 5px}h2{font-size:18px;margin:0}h3{font-size:16px;margin:0}p{margin:6px 0;color:var(--muted)}.eyebrow{font-size:11px;letter-spacing:1.4px;font-weight:750;color:var(--teal);margin-bottom:8px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px}.metric,.panel,.hospital,.match{background:white;border:1px solid var(--line);border-radius:14px}.metric{padding:15px 18px}.metric strong{display:block;font-size:27px}.metric span{color:var(--muted);font-size:12px}.workspace{display:grid;grid-template-columns:340px 1fr;gap:20px;align-items:start}.panel{padding:22px;margin-bottom:20px}.panel-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:16px}label{display:block;margin-top:13px;margin-bottom:6px;font-size:12px;font-weight:650}input,select{width:100%;padding:11px;border:1px solid #ccd8e1;border-radius:8px;background:#fff;color:var(--navy)}input:focus,select:focus{outline:2px solid #8fd7d1}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.full{width:100%;margin-top:18px}.note{font-size:12px;background:#edf7f6;border-radius:8px;padding:12px;margin-top:14px;color:#325d62}.steps{display:flex;gap:7px;flex-wrap:wrap;font-size:11px;color:var(--muted);margin:12px 0}.steps span{padding:5px 8px;background:#edf2f6;border-radius:5px}.badge{display:inline-block;font-size:11px;font-weight:700;padding:4px 8px;border-radius:20px;background:#edf2f6;color:#41566a}.critical{background:#fff0ee;color:#b3312c}.good{background:#e5f6ee;color:#18724c}.urgent{background:#fff6dc;color:#8d6815}.matches{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.match{padding:16px}.match.best{border:2px solid var(--teal);background:#f8fffd}.match.rejected{opacity:.7;background:#f8fafc}.match-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.match .distance{font-size:24px;font-weight:700;margin:9px 0 0}.match .distance small{font-size:12px;font-weight:400}.match button{width:100%;margin-top:10px}.empty{padding:30px;text-align:center;border:1px dashed #c9d6df;border-radius:10px;color:var(--muted)}.request{padding:14px 0;border-bottom:1px solid var(--line)}.request:last-child{border-bottom:0}.request-top{display:flex;justify-content:space-between;gap:8px}.actions{display:flex;gap:7px;margin-top:10px;flex-wrap:wrap}.actions button{padding:7px 11px;font-size:12px}.actions select{width:auto;padding:6px}.hospital-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.hospital{padding:17px}.beds{display:flex;gap:5px;flex-wrap:wrap;margin:6px 0 12px}.bed{width:23px;height:23px;border-radius:5px;border:1px solid #a2d8c1;background:#dff3e9;display:inline-flex;align-items:center;justify-content:center;font-size:10px}.bed.Temporary{background:#fff2ce;border-color:#e6ca77}.bed.Reserved{background:#dceaff;border-color:#a0bdeb}.bed.Occupied{background:#e4e9ef;border-color:#bac5d1}.legend{display:flex;gap:15px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.legend span{display:flex;gap:5px;align-items:center}.legend .bed{width:12px;height:12px}.care-row{display:flex;justify-content:space-between;font-size:12px}.events{max-height:180px;overflow:auto}.event{font-size:12px;padding:8px 0;border-bottom:1px solid var(--line)}.event time{color:var(--muted);margin-right:8px}.toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:var(--navy);color:white;padding:13px 20px;border-radius:10px;z-index:20;max-width:90%;box-shadow:0 8px 30px #102e4933}.hidden{display:none!important}.operator-box{background:#f6f8fb;padding:13px;border-radius:9px}.operator-box input{margin:8px 0}footer{font-size:12px;text-align:center;color:var(--muted);padding:10px 0 24px}#connection{font-size:11px;color:var(--teal)}@media(max-width:1050px){.hospital-grid{grid-template-columns:repeat(2,1fr)}.workspace{grid-template-columns:300px 1fr}}@media(max-width:750px){header,.hero{align-items:flex-start;flex-direction:column}.workspace{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.hospital-grid,.matches{grid-template-columns:1fr}main{padding:20px 4%}h1{font-size:26px}}
</style>
</head>
<body>
