<div><strong style="font-size:10px;text-transform:uppercase;color:#9bc7d0;display:block">{{ $group }}</strong><div style="display:flex;gap:14px;flex-wrap:wrap">@foreach($items as $item)<a style="color:white;text-decoration:none;font-size:12px;padding:5px 0" href="{{ url($item['url']) }}">{{ $item['name'] }}</a>@endforeach</div></div>
