</nav>
<main>
<div class="hero"><div><div class="eyebrow">THE RIGHT CARE, BEFORE THE JOURNEY</div><h1>{{ $demoProfile['role']==='hospital'?'Hospital '.$demoProfile['hospital'].' · Approval desk':'Find a bed. Save the detour.' }}</h1><p>Match care first. Compare distance next. Confirm with the hospital.</p></div>@if($demoProfile['role']!=='hospital')<button class="secondary" id="demoFill">Load accident scenario →</button>@endif</div>
<div class="metrics" id="metrics"></div>
<div class="workspace"><aside>
<section class="panel" @if($demoProfile['role']==='hospital') style="display:none" @endif><div class="panel-head"><h2>Emergency request</h2><span class="badge">01 / Patient</span></div>
<form id="patientForm"><label for="patient">Patient name / ID</label><input id="patient" name="patient" maxlength="80" required placeholder="e.g. Accident Patient 01">
<label for="location">Current location</label><input id="location" name="location" maxlength="120" required placeholder="e.g. Accident Site">
<div class="two"><div><label for="severity">Reported severity</label><select id="severity" name="severity"><option>Critical</option><option>Urgent</option><option>Stable</option></select></div><div><label for="care">Required care</label><select id="care" name="care"><option value="General">General Bed</option><option selected>ICU</option><option>Ventilator</option></select></div></div>
<div class="note">Self-reported severity does not grant priority. Hospital triage verification activates Critical / Urgent priority.</div><button class="full" type="submit">Submit Emergency Request</button></form>
</section>
<section class="panel" id="operatorPanel"><div class="panel-head"><h2>Hospital desk</h2><span id="operatorBadge" class="badge">Role access</span></div><div id="operatorLogin" class="operator-box"><p>Your patient login cannot verify or accept a reservation. After requesting a bed, sign out and use the recommended hospital's operator account. Sign back in here to track your reservation.</p></div><div id="operatorControls" class="hidden"><p>Verify severity, accept requests, then mark arrival. Queue is ordered by verified priority, then submission time. Hospital operators can accept only their own hospital's requests.</p>@if($demoProfile['role']==='admin')<div class="actions"><button class="danger" id="reset">Reset demo data</button></div>@endif</div></section>
<section class="panel"><h2>Priority rules</h2><p class="note">Verified Critical → Urgent → Stable / unverified.<br><br>Critical can reclaim a lower-priority <strong>pending hold</strong>. Confirmed reservations and occupied beds are never displaced. Holds and confirmed reservations expire after 5 minutes unless the patient arrives.</p></section>
</aside><div>
<section class="panel"><div class="panel-head"><h2>Hospital recommendations</h2><span class="badge">02 / Match & request</span></div><select id="selectedRequest" aria-label="Select patient request"></select><div id="selectedSummary"></div><div class="steps"><span>Care compatibility</span><span>→ Distance ranking</span><span>→ Hospital confirmation</span></div><div id="matches" class="matches"></div></section>
<section class="panel"><div class="panel-head"><h2>Request & approval queue</h2><span class="badge">03 / Confirm</span></div><div id="queue"></div></section>
</div></div>
<section class="panel"><div class="panel-head"><div><h2>Hospital bed dashboard</h2><p>Individual beds · mock distances from Accident Site · refresh every 5 seconds</p></div></div><div class="legend"><span><i class="bed"></i>Available</span><span><i class="bed Temporary"></i>Temporary · pending</span><span><i class="bed Reserved"></i>Reserved · accepted</span><span><i class="bed Occupied"></i>Occupied · protected</span></div><div id="hospitals" class="hospital-grid" style="margin-top:16px"></div></section>
<section class="panel"><h2>Decision log</h2><div id="events" class="events"></div></section>
<footer>Prototype only. Seeded availability and fixed distances; no live hospital integration. Expiry runs on the next server read/action.</footer>
</main><div id="toast" class="toast hidden" role="status"></div>
<script>
const stateUrl = @json(url('/emergency/state')), actionUrl = @json(url('/emergency/action'));
const $ = id => document.getElementById(id);
const esc = text => String(text ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, selected = '', busy = false, toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),6000)}
async function refresh(){try{const res=await fetch(stateUrl,{headers:{Accept:'application/json'}});if(!res.ok)throw Error('Server unavailable');data=await res.json();render();$('connection').textContent='● Connected · '+new Date().toLocaleTimeString()}catch(e){$('connection').textContent='Connection unavailable';toast(e.message)}}
async function act(action, payload={}){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{const res=await fetch(actionUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({action,...payload})});const result=await res.json();if(!res.ok)throw Error(result.message || 'Action failed');if(result.id)selected=result.id;toast(result.message);await refresh()}catch(e){toast(e.message)}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
function remaining(r){return r.expires_at ? Math.max(0,r.expires_at-data.now)+'s remaining' : ''}
function render(){
 const beds=data.hospitals.flatMap(h=>h.beds), open=data.hospitals.filter(h=>h.status==='Open');
 $('metrics').innerHTML=[[open.length,'Hospitals accepting requests'],[open.flatMap(h=>h.beds).filter(b=>b.status==='Available').length,'Available care beds'],[data.requests.filter(r=>r.status==='Pending').length,'Awaiting hospital approval'],[beds.filter(b=>b.status==='Reserved').length,'Hospital-confirmed reservations']].map(([n,t])=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`).join('');
 $('operatorBadge').textContent=data.operator?'Hospital role verified':'Patient access';$('operatorLogin').classList.toggle('hidden',data.operator);$('operatorControls').classList.toggle('hidden',!data.operator);
 if(!data.requests.some(r=>r.id===selected))selected=data.requests[0]?.id || '';
 $('selectedRequest').innerHTML=data.requests.length ? data.requests.map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r.patient)} · ${r.care} · ${r.status}</option>`).join('') : '<option>Submit a request to compare hospitals</option>';
 const r=data.requests.find(r=>r.id===selected);
 $('selectedSummary').innerHTML=r?`<p><strong>${esc(r.location)}</strong> · ${esc(r.care)} · <span class="badge ${r.priority===3?'critical':r.priority===2?'urgent':''}">${r.verified?'Verified '+r.severity:'Unverified · standard priority'}</span> <span class="badge">${r.status}</span></p>${['Pending','Reserved','Occupied'].includes(r.status)?`<div class="note">Assigned: <strong>Hospital ${esc(r.hospital_id)}</strong> · ${esc(r.bed_id)} · ${esc(remaining(r))}<br>Cards below show current remaining capacity. Your assigned bed stays with this request.</div>`:''}`:'';
 let best=false;
 $('matches').innerHTML=r?r.matches.map(m=>{const recommended=m.compatible&&!best;if(recommended)best=true;const canRequest=data.profile.role!=='hospital'&&['New','Released','Expired','Rejected'].includes(r.status);return `<article class="match ${recommended?'best':''} ${!m.compatible?'rejected':''}"><div class="match-top"><h3>${m.name}</h3><span class="badge ${recommended?'good':''}">${recommended?'Recommended':m.compatible?'Compatible':'Rejected'}</span></div><div class="distance">${m.distance} <small>km · mock distance</small></div><p>${m.available} ${r.care} beds available${m.reclaimable?` · ${m.reclaimable} lower-priority hold reclaimable`:''}</p>${m.reason?`<p class="critical">${esc(m.reason)}</p>`:''}${m.compatible&&canRequest?`<button data-action="request" data-id="${r.id}" data-hospital="${m.id}">Request ${r.care==='General'?'General':r.care} Bed</button>`:''}</article>`}).join(''):'<div class="empty">Start with the accident scenario. Hospital A has no available ICU bed; Hospital C is the closest compatible option.</div>';
 $('queue').innerHTML=data.requests.length?data.requests.map(r=>`<article class="request"><div class="request-top"><div><strong>${esc(r.patient)}</strong><p>${esc(r.care)} · ${r.hospital_id?'Hospital '+r.hospital_id:'No hospital requested'} · ${esc(remaining(r))}</p></div><div><span class="badge ${r.priority===3?'critical':''}">P${r.priority} · ${r.verified?r.severity:'Unverified'}</span> <span class="badge ${r.status==='Reserved'?'good':''}">${r.status}</span></div></div>${r.status==='Released'?'<p>Temporary hold reassigned for verified Critical care. Select this patient to request another hospital.</p>':''}<div class="actions"><button class="secondary" data-select="${r.id}">View hospitals</button>${data.operator&&['New','Pending'].includes(r.status)?`<select id="triage-${r.id}" aria-label="Verified severity for ${esc(r.patient)}">${['Critical','Urgent','Stable'].map(s=>`<option ${s===r.severity?'selected':''}>${s}</option>`).join('')}</select><button class="secondary" data-action="verify" data-id="${r.id}">Verify severity</button>`:''}${data.operator&&r.status==='Pending'?`<button data-action="accept" data-id="${r.id}">Accept → Reserved</button><button class="danger" data-action="reject" data-id="${r.id}">Reject</button>`:''}${data.operator&&r.status==='Reserved'?`<button data-action="arrive" data-id="${r.id}">Patient arrived → Occupied</button>`:''}</div></article>`).join(''):'<div class="empty">No emergency requests yet.</div>';
 $('hospitals').innerHTML=data.hospitals.map(h=>`<article class="hospital"><div class="match-top"><h3>${h.name}</h3><span class="badge ${h.status==='Open'?'good':''}">${h.status}</span></div><p>${h.distance} km from Accident Site</p>${['General','ICU','Ventilator'].map(c=>{const bs=h.beds.filter(b=>b.care===c);return `<div class="care-row"><strong>${c==='General'?'General Bed':c}</strong><span>${bs.filter(b=>b.status==='Available').length} available</span></div><div class="beds">${bs.map(b=>`<span class="bed ${b.status}" title="${esc(b.id)} · ${b.status}" aria-label="${esc(b.id)} ${b.status}">${b.status==='Occupied'?'×':b.status==='Reserved'?'R':b.status==='Temporary'?'T':'+'}</span>`).join('')}</div>`}).join('')}</article>`).join('');
 $('events').innerHTML=data.events.length?data.events.map(e=>`<div class="event"><time>${new Date(e.at*1000).toLocaleTimeString()}</time>${esc(e.message)}</div>`).join(''):'<p>Actions and allocation decisions will appear here.</p>';
}
$('patientForm').addEventListener('submit',e=>{e.preventDefault();act('create',Object.fromEntries(new FormData(e.target)))});
$('selectedRequest').addEventListener('change',e=>{selected=e.target.value;render()});
if($('demoFill'))$('demoFill').onclick=()=>{$('patient').value='Accident Patient '+String((data?.requests.length || 0)+1).padStart(2,'0');$('location').value='Accident Site';$('severity').value='Critical';$('care').value='ICU';$('patientForm').scrollIntoView({behavior:'smooth',block:'center'})};
if($('reset'))$('reset').onclick=()=>{if(confirm('Reset only the seeded emergency demo data?'))act('reset')};
document.addEventListener('click',e=>{const select=e.target.closest('[data-select]');if(select){selected=select.dataset.select;render();$('selectedRequest').scrollIntoView({behavior:'smooth'});return}const b=e.target.closest('[data-action]');if(!b)return;const payload={id:b.dataset.id};if(b.dataset.hospital)payload.hospital_id=b.dataset.hospital;if(b.dataset.action==='verify')payload.severity=$('triage-'+payload.id).value;act(b.dataset.action,payload)});
refresh();setInterval(()=>{if(!busy && !document.hidden && !document.activeElement?.id?.startsWith('triage-'))refresh()},5000);
</script>
</body></html>
